public sealed class DeferredExecutionTests
{
    [Fact]
    public void DeferredQuery_SeesValuesAddedBeforeEnumeration()
    {
        List<int> source = new() { 1, 2 };
        IEnumerable<int> evens = source.Where(value => value % 2 == 0);

        source.Add(4);

        // Assert.Equal enumerates evens, so the deferred Where runs here.
        Assert.Equal(new[] { 2, 4 }, evens);
    }

    [Fact]
    public void MaterializedQuery_DoesNotChangeWithSource()
    {
        List<int> source = new() { 1, 2 };
        List<int> snapshot = source
            .Where(value => value % 2 == 0)
            .ToList();

        source.Add(4);

        // ToList saved the results before source changed.
        Assert.Equal(new[] { 2 }, snapshot);
    }
}
